PREFIX ex: <https://claims.example.org/vocab#>
PREFIX fin: <https://finance.example.org/vocab#>
PREFIX rsk: <https://risk.example.org/vocab#>
CONSTRUCT {
  ?claim ex:onPolicy ?policy ; ex:severity ?severity ; ex:narrative ?text .
  ?policy ins:policyNumber ?number ; ins:policyExpirationDate ?expires ; fin:costCentre ?costCentre ; fin:budgetOwner ?owner .
} WHERE {
  SERVICE <http://host.docker.internal:7878/d/claims/query> { ?claim ex:onPolicy ?policy ; ex:severity ?severity ; ex:narrative ?text }
  SERVICE <http://ontop:8080/sparql> { ?policy ins:policyNumber ?number ; ins:policyExpirationDate ?expires }
  SERVICE <http://host.docker.internal:7878/d/finance/query> { ?policy fin:costCentre ?costCentre ; fin:budgetOwner ?owner }
}
